 async Task FeverStoryChecks(){feverFixture=true;game.World.Changes.FeverStory=new();ClearEnemies();Teleport(game.World.RouteX(FeverMeetZ)+7,FeverMeetZ);SpawnFeverStory();
  MigrationChecks.Assert(GodotObject.IsInstanceValid(feverHouse)&&GodotObject.IsInstanceValid(feverBoy),"Fever house and boy stream");
  MigrationChecks.Assert(feverBoy.FindChildren("*","CollisionObject3D",true,false).Count==0&&feverSister.FindChildren("*","CollisionObject3D",true,false).Count==0,"Children never enter collision/damage systems");
  TickFeverStory(.1);MigrationChecks.Assert(Fever.Stage==1,"Boy approaches and asks for help");var before=FeverBoyPoint;player.Position=Ground(FeverX+100,FeverZ);FeverAction("accept");MigrationChecks.Assert(Fever.Stage==1,"Remote accept rejected");player.Position=before+Vector3.Right;FeverAction("accept");MigrationChecks.Assert(Fever.Stage==2&&Fever.Owner==CommunityOwner,"Escort accepts nearby player");
  player.Position=Ground(FeverX+100,FeverZ);TickFeverStory(1);MigrationChecks.Assert(FeverBoyPoint==before,"Boy waits for distant escort");
  for(int step=0;step<1500&&Fever.Stage==2;step++){player.Position=FeverBoyPoint+Vector3.Right*2;TickFeverStory(.1);}MigrationChecks.Assert(Fever.Stage==3&&Fever.Waypoint==5,"Boy leads along road and ramp into house");
  DrawFeverStory(.1);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);
  var ray=PhysicsRayQueryParameters3D.Create(FeverPoint(0,1.4f,-1),FeverPoint(0,1.4f,-3));MigrationChecks.Assert(GetWorld3D().DirectSpaceState.IntersectRay(ray).Count>0,"Braced door physically blocks before breach");
  player.Position=FeverPoint(-1.7f,.1f,1.4f);int bandages=game.Life.Bandages;FeverAction("tend");MigrationChecks.Assert(Fever.Stage==4&&game.Life.Bandages==bandages,"Examining sister triggers breach without consuming medicine");
  var saved=Json.Read<ExpeditionFeverStory>(Json.Write(Fever));MigrationChecks.Assert(saved.Stage==4&&saved.Waypoint==5,"Mid-encounter stage serializes");
  TickFeverStory(3.1);DrawFeverStory(.1);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);var mother=infected.Single(e=>e.Id==FeverMotherId);MigrationChecks.Assert(Fever.Stage==5&&mother.Hp==130&&!feverBoy.Visible&&!feverSister.Visible,"Adult combat begins after non-graphic fade");MigrationChecks.Assert(GetWorld3D().DirectSpaceState.IntersectRay(ray).Count==0,"Broken door permits movement and hitscan");
  player.Position=FeverPoint(0,.1f,3);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);var savedPosition=player.Position;player.Velocity=new(0,-2,-4);player.MoveAndSlide();MigrationChecks.Assert(player.Position.Y>feverFloor-.2,"House floor physically supports player");player.Position=savedPosition;
  KillEnemy(mother);TickFeverStory(.1);MigrationChecks.Assert(Fever.Stage==6,"Mother defeat resolves encounter");player.Position=FeverPoint(2.4f,.1f,2.5f);FeverAction("notebook");CloseMenu();FeverAction("notebook");CloseMenu();MigrationChecks.Assert(game.Profile.Journal.Seen.Count(s=>s==FeverJournal)==1,"Aftermath record cannot duplicate");game.Persist();var loaded=new ExpeditionGame(game.PathName);MigrationChecks.Assert(loaded.World.Changes.FeverStory.Stage==6&&loaded.Profile.Journal.Seen.Contains(FeverJournal),"Quest completion and portable journal persist");SpawnFeverStory();MigrationChecks.Assert(!infected.Any(e=>e.Id==FeverMotherId),"Mother cannot respawn after completion");
  feverFixture=false;ClearEnemies();Teleport(0,12);GD.Print("PASS / fever story: approach, range validation, escort/wait/ramp, child damage exclusion, door collision/breach, adult fight, journal deduplication and save continuity");
 }
 async void CaptureFeverStory(){try{feverFixture=true;game.World.Changes.FeverStory=new();ClearEnemies();game.World.Changes.Time=980;Teleport(game.World.RouteX(FeverMeetZ)+7,FeverMeetZ);SpawnFeverStory();TickFeverStory(.1);paused=false;weaponRoot.Visible=false;camera.GlobalPosition=FeverBoyPoint+new Vector3(1,1.5f,3.5f);camera.LookAt(FeverBoyPoint+Vector3.Up*.75f);await ArtShot("fever-01-request");
